import{Gt as hf,Mt as ef,Q as R_,Vt as gb,W as Ov,r as $a,wt as cf}from"./chunk-DfoxBnT3.js";import"./main-W7A6AFIE.js";import{t as G}from"./chunk-D61XJBZ_.js";import{t as v}from"./chunk-B3lYK5z8.js";var p=class s{info=G;static ɵfac=function(r){return new(r||s)};static ɵcmp=ef({type:s,selectors:[[`app-privacy-policy`]],decls:110,vars:6,consts:[[`title`,`Privacy Policy`,`summary`,`A free personal project. Nothing is collected from you for me, and nothing is charged to you.`],[1,`space-y-8`,`text-sm`,`leading-relaxed`,`text-slate-700`],[1,`text-lg`,`font-bold`,`text-slate-900`],[1,`mt-3`,`list-disc`,`space-y-2`,`pl-5`],[1,`mt-3`],[1,`mt-4`,`font-semibold`,`text-slate-900`],[1,`mt-2`]],template:function(r,i){r&1&&($a(0,`app-legal-page`,0)(1,`div`,1)(2,`section`)(3,`h2`,2),R_(4,`1. The short version`),cf(),$a(5,`ul`,3)(6,`li`),R_(7),cf(),$a(8,`li`),R_(9,` I do not run analytics, advertising, tracking pixels or profiling, and I do not sell or share your information. `),cf(),$a(10,`li`),R_(11,` I do not take your data for myself. What exists is what you enter, kept in your own account so the app can work for you. `),cf(),$a(12,`li`),R_(13,` You can export or delete your data at any time, and you can stop using the app whenever you like. `),cf()()(),$a(14,`section`)(15,`h2`,2),R_(16,`2. Who runs this app`),cf(),$a(17,`p`,4),R_(18),cf(),$a(19,`p`,4),R_(20),cf()(),$a(21,`section`)(22,`h2`,2),R_(23,` 3. What I do not collect `),cf(),$a(24,`ul`,3)(25,`li`),R_(26,`No analytics, usage tracking, heatmaps or crash profiling.`),cf(),$a(27,`li`),R_(28,`No advertising identifiers, pixels or remarketing lists.`),cf(),$a(29,`li`),R_(30,` No access to your device's contacts, address book or social accounts. `),cf(),$a(31,`li`),R_(32,`No payment card, bank or billing details.`),cf(),$a(33,`li`),R_(34,`No marketing or newsletter subscriptions.`),cf()(),$a(35,`p`,4),R_(36,` I do not read your business records for my own purposes, and I do not use them to build profiles or train advertising systems. `),cf()(),$a(37,`section`)(38,`h2`,2),R_(39,` 4. What is stored to run the app `),cf(),$a(40,`p`,4),R_(41,` The app cannot work without some information. This is the complete list, and it exists only to provide the service to you: `),cf(),$a(42,`h3`,5),R_(43,` 4.1 Account information `),cf(),$a(44,`p`,6),R_(45,` When you create an account or sign in with Google, I receive your email address, your display name and a unique account identifier. Authentication is handled by Google Firebase Authentication. I never receive or store your Google password. `),cf(),$a(46,`h3`,5),R_(47,` 4.2 Business records you enter `),cf(),$a(48,`p`,6),R_(49,` The information you record in the app — milkman details, daily milk entries, milk rates, payments and your application settings — is stored in your account so it is available on every device you sign in from. It is your data, not mine. `),cf(),$a(50,`h3`,5),R_(51,` 4.3 Security and device information `),cf(),$a(52,`p`,6),R_(53,` To help you review account activity, the app records sign-in sessions and trusted devices, including a timestamp, the browser's user agent string, and the IP address and approximate geographic location reported for that connection. The approximate location is obtained by sending the request's IP address to the third-party service ipwho.is (see section 5). `),cf(),$a(54,`h3`,5),R_(55,`4.4 Preferences`),cf(),$a(56,`p`,6),R_(57,` Formatting choices such as your currency and colour theme are stored with your settings so the app displays consistently on every device. `),cf(),$a(58,`h3`,5),R_(59,`4.5 Contact form`),cf(),$a(60,`p`,6),R_(61,` The name, email address, optional phone number and message you enter on the contact page are used only to reply to you. They are not added to a mailing list and are not used for marketing. `),cf(),$a(62,`p`,6),R_(63,` The form is delivered to my inbox by Web3Forms and protected by an hCaptcha check (see section 5). I keep nothing beyond the reply I send you. `),cf()(),$a(64,`section`)(65,`h2`,2),R_(66,` 5. Service providers `),cf(),$a(67,`p`,4),R_(68,` The app relies on the following third parties. Each processes data only as needed to provide its service, and none of them receives payment from you: `),cf(),$a(69,`ul`,3)(70,`li`)(71,`strong`),R_(72,`Google Firebase`),cf(),R_(73,` (Authentication, Cloud Firestore and Cloud Storage) — hosts your account and your business records. `),cf(),$a(74,`li`)(75,`strong`),R_(76,`ipwho.is`),cf(),R_(77,` — receives the IP address of a sign-in request in order to return an approximate city, region and country for your security activity list. `),cf(),$a(78,`li`)(79,`strong`),R_(80,`Web3Forms`),cf(),R_(81,` — receives the contact form fields and forwards them to my email inbox. `),cf(),$a(82,`li`)(83,`strong`),R_(84,`hCaptcha`),cf(),R_(85,` — checks the contact form for automated submissions. It is used only on the contact page; the rest of the app loads no captcha. `),cf()(),$a(86,`p`,4),R_(87,` Data is transmitted over HTTPS and encrypted in transit by Google. `),cf()(),$a(88,`section`)(89,`h2`,2),R_(90,` 6. Storage on your device `),cf(),$a(91,`p`,4),R_(92,` The app keeps a small amount of data in your browser's local storage: the restored sign-in session and your theme choice. These stay on your device and can be cleared by clearing site data or by signing out. `),cf()(),$a(93,`section`)(94,`h2`,2),R_(95,` 7. Your data, export and deletion `),cf(),$a(96,`p`,4),R_(97,` Your records belong to you. You can export your full database to CSV, PDF or JSON at any time, and import a JSON export on another device from the Data Management settings. `),cf(),$a(98,`p`,4),R_(99),cf()(),$a(100,`section`)(101,`h2`,2),R_(102,`8. Children`),cf(),$a(103,`p`,4),R_(104),cf()(),$a(105,`section`)(106,`h2`,2),R_(107,` 9. Changes to this policy `),cf(),$a(108,`p`,4),R_(109,` I may update this policy as the app changes. Material changes will be reflected in the "Last updated" date above. `),cf()()()()),r&2&&(gb(7),hf(` `,i.info.appName,` is a free personal project. I do not charge you and I do not take payment details from you. `),gb(11),Ov(` `,i.info.appName,` is an independent personal project run by `,i.info.operatorName,`, an individual developer. It is not a company, there is no business entity behind it, and there is no team receiving your information. `),gb(2),hf(` You use `,i.info.appName,` with your own account. The business records you enter are yours. This policy explains where they are stored and when they leave your device. `),gb(79),hf(` Deleting your account removes your records from `,i.info.appName,`. Copies of exported files that you saved to your own device remain under your control and must be deleted by you. `),gb(5),hf(` `,i.info.appName,` is a business tool and is not directed to children. I do not knowingly collect information from children. `))},dependencies:[v],encapsulation:2})};export{p as PrivacyPolicyComponent};